// `pnpm unwired coverage` merges its inputs over the Node suite's map: an entry any input executed is executed, only
// production source is listed, and a harness process's hits never count.
import { execFileSync } from "node:child_process";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { stripTypeScriptTypes } from "node:module";
import { join } from "node:path";
import process from "node:process";
import { pathToFileURL } from "node:url";
import { expect, test } from "@orb/testkit/tooling";
import { inheritedProcessEnv } from "@orb/tooling/floor/process/process-env";
import { transformWithOxc } from "vite";
import { z } from "zod";
import type { CoverageRange } from "../../../tooling/src/floor/testing/coverage-collection.ts";
import { COVERAGE_LAYOUT, flattenHits, sourceFileName } from "../../../tooling/src/floor/testing/coverage-collection.ts";
import { convertBrowserRun, convertNodeRun, istanbulOf } from "../../../tooling/src/unwired/coverage-convert.ts";
import { isProductionSource, istanbulMapSchema, mergeCoverage } from "../../../tooling/src/unwired/coverage-merge.ts";

const SOURCE = "packages/demo/src/pick.ts";
const TEXT = [
  "export function pick(x: number): number {",
  "  if (x > 0) {",
  "    return 1;",
  "  }",
  "  return 2;",
  "}",
  "export function spare(): number {",
  "  return 3;",
  "}",
  "",
].join("\n");

// The ranges V8 reports for one run of the file: the script, `pick` with its untaken tail or block, and `spare`.
function run(opts: { readonly positive: boolean; readonly spare: boolean }): CoverageRange[] {
  const pickStart = TEXT.indexOf("export function pick") + "export ".length;
  const pickEnd = TEXT.indexOf("}\nexport function spare") + 1;
  const block = TEXT.indexOf("{\n    return 1");
  const blockEnd = TEXT.indexOf("}\n  return 2") + 1;
  const spareStart = TEXT.indexOf("function spare");
  const range = (startOffset: number, endOffset: number, count: number): CoverageRange => ({ startOffset, endOffset, count });
  return [
    range(0, TEXT.length, 1),
    range(pickStart, pickEnd, 1),
    opts.positive ? range(blockEnd, pickEnd - 1, 0) : range(block, blockEnd, 0),
    range(spareStart, TEXT.length - 1, opts.spare ? 1 : 0),
  ];
}

function converted(root: string, ranges: readonly CoverageRange[]): ReturnType<typeof istanbulOf> {
  const path = join(root, SOURCE);
  const segments = flattenHits([{ functionName: "", isBlockCoverage: true, ranges }]);
  return istanbulOf(pathToFileURL(path).href, stripTypeScriptTypes(TEXT, { mode: "strip" }), segments);
}

test("a function or branch arm one input ran and another did not counts as executed", { timeout: 30_000 }, async ({ plantedTree }) => {
  const root = await plantedTree({ [SOURCE]: TEXT });
  const node = await converted(root, run({ positive: true, spare: false }));
  const ct = await converted(root, run({ positive: false, spare: true }));
  const alone = mergeCoverage(root, [{ suite: "node", map: node }]);
  expect(alone.unexecuted).toEqual([{ file: SOURCE, functions: [{ name: "spare", line: 7 }], branches: [{ type: "if", line: 2, arm: 1 }] }]);
  const merged = mergeCoverage(root, [
    { suite: "node", map: node },
    { suite: "ct", map: ct },
  ]);
  expect(merged.unexecuted).toEqual([]);
  expect(merged.totals).toEqual({ files: 1, functions: 2, functionsUnexecuted: 0, branchArms: 2, branchArmsUnexecuted: 0 });
  expect(merged.projections.ct?.unmatchedFunctions).toBe(0);
});

test("only production source under packages/*/src is in scope", () => {
  // A generated file is known by its generator's header or a `.gen.` name, never by another name.
  const generatedHead = (rel: string): string =>
    rel.endsWith("table.ts") || rel.endsWith("support.generated.ts") ? "// GENERATED by a script; do not hand-edit.\n" : "export const x = 1;\n";
  const inScope = [
    "packages/kit/src/ids/index.ts",
    "packages/client/src/app.tsx",
    "packages/kit/src/ids/types.d.ts",
    "packages/ui/src/tokens/themes.gen.ts",
    "packages/plugin-toolchain/src/support.generated.ts",
    "packages/kit/src/handle-key/table.ts",
    "packages/client/vite.config.ts",
    "packages/client/node_modules/x/src/a.ts",
    "tests/kit/ids.test.ts",
    "tooling/src/unwired/run.ts",
  ].filter((rel) => isProductionSource(rel, generatedHead));
  expect(inScope).toEqual(["packages/kit/src/ids/index.ts", "packages/client/src/app.tsx"]);
});

test("a process that loaded harness code contributes no hits, a product process does", { timeout: 30_000 }, async ({ plantedTree }) => {
  const root = await plantedTree({ [SOURCE]: TEXT, "tooling/src/stack/cli.ts": "export {};\n" });
  const runDir = join(root, "run");
  const dumps = join(runDir, COVERAGE_LAYOUT.node);
  mkdirSync(dumps, { recursive: true });
  const script = (rel: string, ranges: readonly CoverageRange[]): object => ({
    scriptId: "1",
    url: pathToFileURL(join(root, rel)).href,
    functions: [{ functionName: "", isBlockCoverage: true, ranges }],
  });
  const everything = run({ positive: true, spare: true });
  // The supervisor ran the whole file; were its hits kept, `spare` would read as executed.
  writeFileSync(
    join(dumps, "coverage-1.json"),
    JSON.stringify({ result: [script("tooling/src/stack/cli.ts", [{ startOffset: 0, endOffset: 10, count: 1 }]), script(SOURCE, everything)] }),
  );
  writeFileSync(join(dumps, "coverage-2.json"), JSON.stringify({ result: [script(SOURCE, run({ positive: true, spare: false }))] }));
  const merged = mergeCoverage(root, [{ suite: "e2e", map: await convertNodeRun(root, runDir) }]);
  expect(merged.unexecuted.flatMap((file) => file.functions)).toEqual([{ name: "spare", line: 7 }]);
});

test("real Node dumps keep the product process and drop the harness process", { timeout: 30_000 }, async ({ plantedTree }) => {
  const root = await plantedTree({
    [SOURCE]: TEXT,
    "packages/demo/src/main.ts": 'import { pick } from "./pick.ts";\npick(1);\n',
    // The harness calls `spare`; were its process kept, `spare` would read as executed.
    "tooling/src/cli.ts": 'import { pick, spare } from "../../packages/demo/src/pick.ts";\npick(-1);\nspare();\n',
  });
  const runDir = join(root, "run");
  for (const entry of ["packages/demo/src/main.ts", "tooling/src/cli.ts"]) {
    // Node itself writes the dumps, as the e2e server does under `NODE_V8_COVERAGE`.
    execFileSync(process.execPath, [join(root, entry)], {
      env: inheritedProcessEnv(Object.fromEntries([["NODE_V8_COVERAGE", join(runDir, COVERAGE_LAYOUT.node)]])),
    });
  }
  const merged = mergeCoverage(root, [{ suite: "e2e", map: await convertNodeRun(root, runDir) }]);
  expect(merged.unexecuted).toEqual([{ file: SOURCE, functions: [{ name: "spare", line: 7 }], branches: [{ type: "if", line: 2, arm: 1 }] }]);
  // The product entry is listed in scope and fully ran; the harness entry is outside scope either way.
  expect(merged.totals.files).toBe(2);
});

test("a browser chunk's hits land on the Node suite's entries through its inline map", { timeout: 30_000 }, async ({ plantedTree }) => {
  const root = await plantedTree({ [SOURCE]: TEXT });
  const path = join(root, SOURCE);
  // A transformed chunk with a map, sources absolute as the coverage build writes them.
  const built = await transformWithOxc(TEXT, path, { sourcemap: true });
  const map = { ...built.map, sources: [path] };
  const url = "http://127.0.0.1:5173/assets/pick.js";
  const code = `${built.code}\n//# sourceMappingURL=data:application/json;base64,${Buffer.from(JSON.stringify(map)).toString("base64")}\n`;
  const spareAt = code.indexOf("function spare");
  const runDir = join(root, "run");
  mkdirSync(join(runDir, COVERAGE_LAYOUT.browser), { recursive: true });
  mkdirSync(join(runDir, COVERAGE_LAYOUT.sources), { recursive: true });
  writeFileSync(join(runDir, COVERAGE_LAYOUT.sources, sourceFileName(url)), code);
  const segments = flattenHits([
    {
      functionName: "",
      isBlockCoverage: true,
      ranges: [
        { startOffset: 0, endOffset: code.length, count: 1 },
        { startOffset: spareAt, endOffset: code.indexOf("}", spareAt) + 1, count: 1 },
      ],
    },
  ]);
  writeFileSync(
    join(runDir, COVERAGE_LAYOUT.browser, "1-0.json"),
    JSON.stringify({ specs: ["tests/demo/pick.ct.tsx"], lost: [], scripts: [{ url, source: sourceFileName(url), segments }] }),
  );
  const browser = await convertBrowserRun(runDir);
  expect(browser.specs).toEqual(["tests/demo/pick.ct.tsx"]);
  const node = await converted(root, run({ positive: true, spare: false }));
  const merged = mergeCoverage(root, [
    { suite: "node", map: node },
    { suite: "ct", map: browser.map },
  ]);
  expect(merged.unexecuted.flatMap((file) => file.functions)).toEqual([]);
  expect(merged.projections.ct?.unmatchedFunctions).toBe(0);
});

test("a compiled copy lands on its source function by name and line, or as the one anonymous function on its line", ({ plantedTree }) => {
  return plantedTree({ [SOURCE]: TEXT }).then((root) => {
    const path = join(root, SOURCE);
    const range = (line: number, column: number): { start: { line: number; column: number }; end: { line: number; column: number } } => ({
      start: { line, column },
      end: { line, column: column + 1 },
    });
    const file = (
      fns: readonly { readonly name: string; readonly line: number; readonly decl: number; readonly hit: number }[],
    ): Awaited<ReturnType<typeof istanbulOf>> => ({
      [path]: {
        path,
        fnMap: Object.fromEntries(fns.map((fn, index) => [String(index), { name: fn.name, decl: range(fn.line, fn.decl), loc: range(fn.line, fn.decl) }])),
        f: Object.fromEntries(fns.map((fn, index) => [String(index), fn.hit])),
        branchMap: {},
        b: {},
      },
    });
    // The Node copy names `Stack` at its identifier; the compiled browser copy starts at the `function` keyword. Line 2
    // holds one anonymous callback, line 3 two, so only line 2's moved copy has one place to land.
    const node = file([
      { name: "Stack", line: 1, decl: 16, hit: 0 },
      { name: "(anonymous_1)", line: 2, decl: 30, hit: 0 },
      { name: "(anonymous_2)", line: 3, decl: 10, hit: 0 },
      { name: "(anonymous_3)", line: 3, decl: 40, hit: 0 },
    ]);
    const ct = file([
      { name: "Stack", line: 1, decl: 7, hit: 1 },
      { name: "(anonymous_4)", line: 2, decl: 28, hit: 1 },
      { name: "(anonymous_5)", line: 3, decl: 12, hit: 1 },
    ]);
    const merged = mergeCoverage(root, [
      { suite: "node", map: node },
      { suite: "ct", map: ct },
    ]);
    expect(merged.unexecuted.flatMap((entry) => entry.functions)).toEqual([
      { name: "(anonymous_2)", line: 3 },
      { name: "(anonymous_3)", line: 3 },
    ]);
    expect(merged.projections.ct).toMatchObject({ matchedFunctions: 2, unmatchedFunctions: 1 });
  });
});

test("a bundler's `$<n>` suffix drops only at the declared point, after a source's own `$` name had its turn", ({ plantedTree }) => {
  return plantedTree({ [SOURCE]: TEXT }).then((root) => {
    const path = join(root, SOURCE);
    const range = (line: number, column: number): { start: { line: number; column: number }; end: { line: number; column: number } } => ({
      start: { line, column },
      end: { line, column: column + 1 },
    });
    const file = (fns: readonly { readonly name: string; readonly column: number; readonly hit: number }[]): Awaited<ReturnType<typeof istanbulOf>> => ({
      [path]: {
        path,
        fnMap: Object.fromEntries(fns.map((fn, index) => [String(index), { name: fn.name, decl: range(5, fn.column), loc: range(5, fn.column) }])),
        f: Object.fromEntries(fns.map((fn, index) => [String(index), fn.hit])),
        branchMap: {},
        b: {},
      },
    });
    // The source declares both `validateProperty$1` and `validateProperty` on line 5, as react-dom does.
    const universe = file([
      { name: "validateProperty$1", column: 9, hit: 0 },
      { name: "validateProperty", column: 40, hit: 0 },
    ]);
    const unexecuted = (ct: Awaited<ReturnType<typeof istanbulOf>>): readonly string[] =>
      mergeCoverage(root, [
        { suite: "node", map: universe },
        { suite: "ct", map: ct },
      ]).unexecuted.flatMap((entry) => entry.functions.map((fn) => fn.name));
    // A moved copy of the source's own `validateProperty$1` sits at its twin's point: its own name on its line wins.
    expect(unexecuted(file([{ name: "validateProperty$1", column: 40, hit: 1 }]))).toEqual(["validateProperty"]);
    // A renamed copy at the twin's declared point is the twin.
    expect(unexecuted(file([{ name: "validateProperty$2", column: 40, hit: 1 }]))).toEqual(["validateProperty$1"]);
    // Control: at a point no function declares, a renamed name matches nothing, though its line holds that name.
    expect(unexecuted(file([{ name: "validateProperty$2", column: 70, hit: 1 }]))).toEqual(["validateProperty$1", "validateProperty"]);
  });
});

// A real vitest json entry, counts zeroed, and the source it was recorded from.
const recorded = z
  .object({ source: z.string(), entry: z.record(z.string(), z.unknown()) })
  .parse(JSON.parse(readFileSync(join(import.meta.dirname, "_vitest-universe.json"), "utf8")));

test("server code an e2e run executed lands on a real vitest universe whose columns drift", { timeout: 30_000 }, async ({ plantedTree }) => {
  // A recorded vitest entry: two anonymous functions share line 7, and vitest's mapped-back columns differ from the
  // type-stripped text Node runs, so no start position agrees for them.
  const rel = "packages/demo/src/session-policy.ts";
  const root = await plantedTree({ [rel]: recorded.source });
  const path = join(root, rel);
  const node = istanbulMapSchema.parse({ [path]: { ...recorded.entry, path } });
  const code = stripTypeScriptTypes(recorded.source, { mode: "strip" });
  const e2e = await istanbulOf(pathToFileURL(path).href, code, [{ startOffset: 0, endOffset: code.length, count: 1 }]);
  // Control: the drift is real, so exact positions alone would leave hits unmatched.
  const vitestAt = new Set(Object.values(node[path]?.fnMap ?? {}).map((fn) => `${String(fn.decl.start.line)}:${String(fn.decl.start.column)}`));
  expect(
    Object.values(e2e[path]?.fnMap ?? {}).filter((fn) => !vitestAt.has(`${String(fn.decl.start.line)}:${String(fn.decl.start.column)}`)).length,
  ).toBeGreaterThan(0);
  const merged = mergeCoverage(root, [
    { suite: "node", map: node },
    { suite: "e2e", map: e2e },
  ]);
  expect(merged.unexecuted.flatMap((entry) => entry.functions)).toEqual([]);
  expect(merged.projections.e2e).toMatchObject({ unmatchedFunctions: 0, unmatchedArms: 0 });
});

test("a moved named function lands by the line its range starts on when its declared line moved too", ({ plantedTree }) => {
  return plantedTree({ [SOURCE]: TEXT }).then((root) => {
    const path = join(root, SOURCE);
    const range = (line: number, column: number): { start: { line: number; column: number }; end: { line: number; column: number } } => ({
      start: { line, column },
      end: { line, column: column + 1 },
    });
    const one = (decl: readonly [number, number], loc: readonly [number, number], hit: number): Awaited<ReturnType<typeof istanbulOf>> => ({
      [path]: { path, fnMap: { "0": { name: "Stack", decl: range(...decl), loc: range(...loc) } }, f: { "0": hit }, branchMap: {}, b: {} },
    });
    // The Node copy declares `Stack` on line 17; the compiled copy names line 16 and starts its range on line 17.
    const merged = mergeCoverage(root, [
      { suite: "node", map: one([17, 16], [88, 29], 0) },
      { suite: "ct", map: one([16, 0], [17, 7], 1) },
    ]);
    expect(merged.unexecuted).toEqual([]);
    // Control: a copy whose lines match neither stays unmatched and the function stays unexecuted.
    const apart = mergeCoverage(root, [
      { suite: "node", map: one([17, 16], [88, 29], 0) },
      { suite: "ct", map: one([30, 0], [31, 7], 1) },
    ]);
    expect(apart.unexecuted.flatMap((entry) => entry.functions)).toEqual([{ name: "Stack", line: 17 }]);
  });
});

// The universe of a line with two anonymous functions, as vitest records it.
function twoArrows(path: string): Awaited<ReturnType<typeof istanbulOf>> {
  const r = (l: number, c: number, c2: number): { start: { line: number; column: number }; end: { line: number; column: number } } => ({
    start: { line: l, column: c },
    end: { line: l, column: c2 },
  });
  return {
    [path]: {
      path,
      fnMap: {
        "0": { name: "(anonymous_14)", decl: r(7, 87, 88), loc: r(7, 109, 120) },
        "1": { name: "(anonymous_15)", decl: r(7, 120, 121), loc: r(7, 136, 153) },
      },
      f: { "0": 0, "1": 0 },
      branchMap: {},
      b: {},
    },
  };
}

test("a compiled copy whose declared point and range start name two different functions lands on neither", ({ plantedTree }) => {
  return plantedTree({ [SOURCE]: TEXT }).then((root) => {
    const path = join(root, SOURCE);
    const r = (c: number, c2: number): { start: { line: number; column: number }; end: { line: number; column: number } } => ({
      start: { line: 7, column: c },
      end: { line: 7, column: c2 },
    });
    const copy = (decl: readonly [number, number], loc: readonly [number, number]): Awaited<ReturnType<typeof istanbulOf>> => ({
      [path]: { path, fnMap: { "0": { name: "(anonymous_14)", decl: r(...decl), loc: r(...loc) } }, f: { "0": 1 }, branchMap: {}, b: {} },
    });
    const both = [
      { name: "(anonymous_14)", line: 7 },
      { name: "(anonymous_15)", line: 7 },
    ];
    // The React Compiler gives the second arrow of a ternary the first arrow's declared point.
    const stolenDecl = mergeCoverage(root, [
      { suite: "node", map: twoArrows(path) },
      { suite: "ct", map: copy([87, 88], [136, 150]) },
    ]);
    expect(stolenDecl.unexecuted.flatMap((entry) => entry.functions)).toEqual(both);
    expect(stolenDecl.projections.ct).toMatchObject({ matchedFunctions: 0, unmatchedFunctions: 1 });
    // The reverse: the declared point is right and the range start is the other function's.
    const stolenLoc = mergeCoverage(root, [
      { suite: "node", map: twoArrows(path) },
      { suite: "ct", map: copy([120, 121], [109, 115]) },
    ]);
    expect(stolenLoc.unexecuted.flatMap((entry) => entry.functions)).toEqual(both);
    // A declared point that names no function leaves the range start to place the hit, with no line count to agree on.
    const movedDecl = mergeCoverage(root, [
      { suite: "node", map: twoArrows(path) },
      { suite: "ct", map: copy([100, 101], [136, 150]) },
    ]);
    expect(movedDecl.unexecuted.flatMap((entry) => entry.functions)).toEqual([{ name: "(anonymous_14)", line: 7 }]);
    // Control: when both keys name one function, the hit lands on it.
    const agreed = mergeCoverage(root, [
      { suite: "node", map: twoArrows(path) },
      { suite: "ct", map: copy([120, 121], [136, 150]) },
    ]);
    expect(agreed.unexecuted.flatMap((entry) => entry.functions)).toEqual([{ name: "(anonymous_14)", line: 7 }]);
  });
});

test("a moved branch lands by its place among its line's branches of its type, only with the same arm count", ({ plantedTree }) => {
  return plantedTree({ [SOURCE]: TEXT }).then((root) => {
    const path = join(root, SOURCE);
    const at = (c: number): { start: { line: number; column: number }; end: { line: number; column: number } } => ({
      start: { line: 2, column: c },
      end: { line: 2, column: c + 5 },
    });
    // Each branch is [column, hits per arm].
    const branches = (shape: readonly (readonly [number, readonly number[]])[]): Awaited<ReturnType<typeof istanbulOf>> =>
      istanbulMapSchema.parse({
        [path]: {
          path,
          fnMap: {},
          f: {},
          branchMap: Object.fromEntries(
            shape.map(([column, hits], index) => [String(index), { type: "binary-expr", loc: at(column), locations: hits.map(() => at(column)) }]),
          ),
          b: Object.fromEntries(shape.map(([, hits], index) => [String(index), [...hits]])),
        },
      });
    const universe = branches([
      [10, [0, 0]],
      [30, [0, 0, 0]],
    ]);
    // Every column moved; the last operand of the second branch ran.
    const moved = mergeCoverage(root, [
      { suite: "node", map: universe },
      {
        suite: "ct",
        map: branches([
          [12, [0, 0]],
          [35, [0, 0, 1]],
        ]),
      },
    ]);
    expect(moved.unexecuted.flatMap((entry) => entry.branches).map((branch) => branch.arm)).toEqual([0, 0, 1, 1]);
    expect(moved.projections.ct).toMatchObject({ matchedArms: 1, unmatchedArms: 0 });
    // A copy with another arm count at that place is another construct: its hit stays unmatched.
    const reshaped = mergeCoverage(root, [
      { suite: "node", map: universe },
      {
        suite: "ct",
        map: branches([
          [12, [0, 0]],
          [35, [0, 1]],
        ]),
      },
    ]);
    expect(reshaped.projections.ct).toMatchObject({ matchedArms: 0, unmatchedArms: 1 });
  });
});

type Spot = readonly [line: number, column: number];

// Each branch is [type, start, end, hits per arm]; a branch's arms share its span, which the merge never reads.
function spans(path: string, shape: readonly (readonly [string, Spot, Spot, readonly number[]])[]): Awaited<ReturnType<typeof istanbulOf>> {
  const range = ([line, column]: Spot, [endLine, endColumn]: Spot): { start: { line: number; column: number }; end: { line: number; column: number } } => ({
    start: { line, column },
    end: { line: endLine, column: endColumn },
  });
  return istanbulMapSchema.parse({
    [path]: {
      path,
      fnMap: {},
      f: {},
      branchMap: Object.fromEntries(
        shape.map(([type, start, end, hits], index) => [String(index), { type, loc: range(start, end), locations: hits.map(() => range(start, end)) }]),
      ),
      b: Object.fromEntries(shape.map(([, , , hits], index) => [String(index), [...hits]])),
    },
  });
}

test("branches that start at one point are each counted and each matched by its arm count", ({ plantedTree }) => {
  return plantedTree({ [SOURCE]: TEXT }).then((root) => {
    const path = join(root, SOURCE);
    // A two-arm and a three-arm logical branch that start at one point, as `a ?? b` over `a || b || c` does.
    const universe = spans(path, [
      ["binary-expr", [2, 22], [2, 90], [0, 0]],
      ["binary-expr", [2, 22], [2, 60], [0, 0, 0]],
    ]);
    const merged = mergeCoverage(root, [
      { suite: "node", map: universe },
      { suite: "ct", map: spans(path, [["binary-expr", [2, 22], [2, 90], [1, 0]]]) },
    ]);
    expect(merged.totals.branchArms).toBe(5);
    expect(merged.projections.ct).toMatchObject({ matchedArms: 1, unmatchedArms: 0 });
    // The two-arm branch lost only its executed first arm; the three-arm one lost none.
    expect(merged.unexecuted.flatMap((entry) => entry.branches.map((branch) => branch.arm))).toEqual([0, 1, 1, 2]);
  });
});

test("a branch whose start moved lands by where it ends, and only with the same arm count", ({ plantedTree }) => {
  return plantedTree({ [SOURCE]: TEXT }).then((root) => {
    const path = join(root, SOURCE);
    // The source tests a `const` declared on line 2 at line 3; the build inlines it, so the conditional starts on line 2.
    const universe = spans(path, [["cond-expr", [3, 9], [3, 40], [0, 0]]]);
    const armsOf = (build: ReturnType<typeof spans>): { readonly unexecuted: readonly number[]; readonly unmatchedArms: number | undefined } => {
      const merged = mergeCoverage(root, [
        { suite: "node", map: universe },
        { suite: "ct", map: build },
      ]);
      return {
        unexecuted: merged.unexecuted.flatMap((entry) => entry.branches.map((branch) => branch.arm)),
        unmatchedArms: merged.projections.ct?.unmatchedArms,
      };
    };
    expect(armsOf(spans(path, [["cond-expr", [2, 20], [3, 40], [1, 0]]]))).toEqual({ unexecuted: [1], unmatchedArms: 0 });
    // Controls: the same start line but another end line, and another arm count at the same end, are other constructs.
    expect(armsOf(spans(path, [["cond-expr", [2, 20], [4, 40], [1, 0]]]))).toEqual({ unexecuted: [0, 1], unmatchedArms: 1 });
    expect(armsOf(spans(path, [["cond-expr", [2, 20], [3, 40], [1, 0, 0]]]))).toEqual({ unexecuted: [0, 1], unmatchedArms: 1 });
  });
});
